(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-237":{scenario:{company:"Vịnh Ngọc Container Terminal",supervisor:{name:"Phan Văn Lực",role:{vi:"Trưởng ca Điều độ Bãi",en:"Yard Planning Shift Supervisor"}},ref_code:"YP-0517",title:{vi:"Đúng khu bãi. Đúng phí lưu bãi.",en:"Right yard block. Right storage charge."},brief:{vi:"Container 20' chứa sơn dung môi, hàng nguy hiểm IMDG loại 3, dỡ xuống bãi ngày 03/11 và chủ hàng lấy ra ngày 14/11. Sơ đồ bãi có block G04 (hàng khô thường), DG1 (hàng nguy hiểm, có tách biệt và thiết bị chữa cháy), RF2 (hàng lạnh có ổ cắm điện). Đối chiếu kế hoạch bãi nháp YP-0517 với hồ sơ đã duyệt, sửa block xếp container và phí lưu bãi (VND, biểu giá mô phỏng), rồi lập báo cáo có căn cứ.",en:"A 20' container of solvent-based paint, IMDG class 3 dangerous goods, was discharged to the yard on 03/11 and collected by the consignee on 14/11. The yard has block G04 (general dry cargo), DG1 (dangerous goods, segregated, with firefighting equipment) and RF2 (reefers with power plugs). Compare draft yard plan YP-0517 with the approved file, correct the yard block and the storage charge (VND, simulated tariff), then write an evidence-based report."},reference_title:{vi:"Sơ đồ bãi & biểu cước lưu bãi đã duyệt · YP-0517",en:"Approved yard map & storage tariff · YP-0517"},fields:[{id:"YARD_BLOCK",label:{vi:"Block xếp container",en:"Assigned yard block"},initial:"G04",expected:"DG1",choices:["G04","DG1","RF2"],reference:"Sơ đồ bãi & quy định hàng nguy hiểm",hint:{vi:"Container hàng nguy hiểm phải xếp ở khu chuyên dụng có tách biệt theo IMDG, không xếp chung hàng thường.",en:"Dangerous goods containers belong in a dedicated area segregated per IMDG, never among general cargo."}},{id:"STORAGE_VND",label:{vi:"Phí lưu bãi (VND)",en:"Storage charge (VND)"},initial:"270000",expected:"630000",reference:"Biểu cước lưu bãi",ref_value:{vi:"Miễn phí 5 ngày; 45000 đ/ngày cho 20' thường; hàng nguy hiểm phụ thu 100% (mô phỏng)",en:"5 free days; 45000 VND/day for a standard 20'; dangerous goods surcharge 100% (simulated)"},hint:{vi:"Đếm cả ngày dỡ và ngày lấy ra, trừ ngày miễn phí rồi áp hệ số hàng nguy hiểm.",en:"Count both the discharge day and the gate-out day, deduct free days, then apply the dangerous goods factor."}}],sop32:{vi:"Số ngày lưu bãi tính cả ngày dỡ xuống và ngày lấy ra; phí lưu bãi = (số ngày lưu - số ngày miễn phí) x đơn giá ngày x (1 + tỷ lệ phụ thu hàng nguy hiểm).",en:"Storage days include both the discharge day and the gate-out day; storage charge = (storage days - free days) x daily rate x (1 + dangerous goods surcharge rate)."},context:{label:"TOS / YP-0517",metrics:[{label:{vi:"Ngày dỡ xuống bãi",en:"Discharge date"},value:"03/11"},{label:{vi:"Ngày lấy ra",en:"Gate-out date"},value:"14/11"},{label:{vi:"Loại IMDG",en:"IMDG class"},value:"3"}]},crisis:{vi:"Tổ trưởng bốc xếp nhắn: “Block DG1 gần đầy, để tạm container sơn ở G04 cạnh dãy hàng lạnh qua đêm, mai chuyển. Đừng cập nhật TOS cho đỡ rắc rối.”",en:"The stevedoring foreman messages you: “DG1 is almost full, park the paint box in G04 next to the reefer row overnight and move it tomorrow. Don't update the TOS, it's less hassle.”"},options:{safe:{vi:"Không xếp hàng nguy hiểm sai khu; bố trí vị trí còn trống ở DG1 hoặc khu dự phòng hàng nguy hiểm được duyệt, cập nhật TOS đúng thực tế, báo trưởng ca và cán bộ an toàn.",en:"Do not misplace dangerous goods; use a free slot in DG1 or the approved DG overflow area, update the TOS accurately and inform the shift supervisor and the safety officer."},shortcut:{vi:"Để tạm container ở G04 qua đêm và không cập nhật TOS như tổ trưởng đề nghị.",en:"Park the container in G04 overnight and leave the TOS unchanged as the foreman suggests."},wait:{vi:"Để container nằm trên xe đầu kéo chờ đến sáng, không báo ai.",en:"Leave the container on the terminal tractor until morning and tell no one."}},questions:{vi:["Vì sao container phải xếp ở DG1 thay vì G04? Quy định tách biệt nào chứng minh?","Trình bày cách tính phí lưu bãi và rủi ro an toàn, pháp lý nếu xếp hàng nguy hiểm sai khu hoặc không cập nhật TOS."],en:["Why must the container go to DG1 instead of G04? Which segregation rule proves it?","Explain how you calculated the storage charge and the safety and legal risks of misplacing dangerous goods or not updating the TOS."]},hints:{vi:["Đặt kế hoạch nháp cạnh sơ đồ bãi đã duyệt, đánh dấu container hàng nguy hiểm đang ở khu thường.","Đếm ngày lưu bãi theo SOP mục 3.2, trừ ngày miễn phí rồi áp phụ thu hàng nguy hiểm.","Đọc lại SOP mục 4.2: vị trí hàng nguy hiểm phải đúng khu và đúng dữ liệu TOS; áp lực làm tắt phải báo cáo."],en:["Place the draft plan next to the approved yard map and flag the DG container sitting in a general block.","Count storage days per SOP 3.2, deduct free days and apply the dangerous goods surcharge.","Re-read SOP 4.2: DG positions must be in the right area and match TOS data; shortcut pressure must be escalated."]}},learning:{summary:{vi:"Chuyên viên khai thác cảng và bãi container lập kế hoạch bãi, điều độ thiết bị xếp dỡ, kiểm soát giao nhận container qua cổng và giám sát hàng lạnh, hàng nguy hiểm trên hệ thống quản lý khai thác cảng (TOS). Mục tiêu là giải phóng tàu nhanh, bãi thông thoáng, dữ liệu vị trí chính xác, tính phí đúng biểu cước và tuyệt đối an toàn cho người, hàng hóa, thiết bị.",en:"A port and container yard operations officer plans the yard, dispatches handling equipment, controls container gate transactions and monitors reefers and dangerous goods in the terminal operating system (TOS). The goal is fast vessel turnaround, a fluid yard, accurate position data, correct tariff charging and full safety for people, cargo and equipment."},responsibilities:{vi:["Lập kế hoạch bãi theo tàu, hãng tàu, loại container, trọng lượng và cảng đích.","Điều độ thiết bị xếp dỡ: cẩu bờ, cẩu khung bánh lốp, xe nâng container, xe đầu kéo nội bộ.","Kiểm soát giao nhận qua cổng: lệnh giao hàng, tình trạng thủ tục hải quan, niêm phong, hư hỏng vỏ.","Giám sát container lạnh cắm điện và container hàng nguy hiểm theo khu tách biệt.","Đối chiếu dữ liệu TOS với thực tế, tính phí lưu bãi và báo cáo năng suất khai thác."],en:["Plan the yard by vessel, carrier, container type, weight and port of discharge.","Dispatch handling equipment: ship-to-shore cranes, RTGs, reach stackers and terminal tractors.","Control gate transactions: delivery orders, customs status, seals and container damage.","Monitor plugged-in reefers and DG containers in their segregated areas.","Reconcile TOS data with the yard, calculate storage charges and report productivity."]},competencies:[{name:{vi:"Lập kế hoạch bãi",en:"Yard planning"},desc:{vi:"Phân khu, xếp tầng theo trọng lượng và cảng đích để giảm đảo chuyển, tăng năng suất.",en:"Zone and stack by weight and destination to cut rehandles and raise productivity."}},{name:{vi:"Điều độ thiết bị",en:"Equipment dispatch"},desc:{vi:"Cân đối cẩu, xe nội bộ theo kế hoạch tàu và giờ cao điểm tại cổng.",en:"Balance cranes and tractors against vessel plans and gate peaks."}},{name:{vi:"Hàng nguy hiểm & an toàn",en:"Dangerous goods & safety"},desc:{vi:"Áp dụng quy tắc tách biệt IMDG, khu bãi chuyên dụng và quy trình ứng phó sự cố.",en:"Apply IMDG segregation, dedicated yard areas and emergency response procedures."}},{name:{vi:"Chính xác dữ liệu TOS",en:"TOS data accuracy"},desc:{vi:"Cập nhật vị trí, trạng thái, niêm phong theo thời gian thực, không để lệch hệ thống.",en:"Update positions, statuses and seals in real time so the system never drifts from reality."}},{name:{vi:"Phối hợp đa bên",en:"Multi-party coordination"},desc:{vi:"Làm việc với hãng tàu, hải quan, chủ hàng, đơn vị vận tải và đội bốc xếp.",en:"Work with carriers, customs, cargo owners, hauliers and stevedoring teams."}}],knowledge:{vi:["Bộ luật IMDG của IMO: phân loại hàng nguy hiểm và bảng tách biệt khi xếp, lưu container.","Yêu cầu VGM theo Công ước SOLAS đối với container xuất khẩu trước khi xếp lên tàu.","Luật Hải quan 2014 (số 54/2014/QH13): hàng chỉ được đưa ra khỏi khu vực giám sát hải quan khi đủ điều kiện về thủ tục.","ISO 6346 về mã hiệu container và ISO 668 về kích thước, khối lượng tối đa của container.","Bộ luật ISPS về an ninh tàu biển và bến cảng.","Chỉ số khai thác: số lần nâng hạ mỗi giờ của cẩu, thời gian lưu bãi, hệ số sử dụng bãi theo TEU."],en:["The IMO IMDG Code: dangerous goods classes and segregation tables for stowing and storing containers.","The SOLAS VGM requirement for export containers before loading.","Customs Law 2014 (No. 54/2014/QH13): goods may leave the customs-controlled area only when formalities are met.","ISO 6346 on container identification and ISO 668 on container dimensions and maximum gross mass.","The ISPS Code on ship and port facility security.","Terminal indicators: crane moves per hour, dwell time and yard utilization in TEU."]},tools:["Hệ thống quản lý khai thác cảng (TOS)","Cổng tự động nhận dạng số container, biển số (OCR)","Thiết bị đầu cuối trên cẩu và xe nội bộ (VMT)","Hệ thống giám sát container lạnh","Phần mềm lập sơ đồ xếp tàu"],kpis:{vi:["Năng suất cẩu bờ (số lần nâng hạ mỗi giờ).","Thời gian lưu bãi bình quân và hệ số sử dụng bãi.","Thời gian xe chờ tại cổng và trong bãi.","Tỷ lệ sai lệch vị trí giữa TOS và thực tế (mục tiêu bằng 0)."],en:["Quay crane productivity (moves per hour).","Average dwell time and yard utilization.","Truck turnaround time at the gate and in the yard.","Position mismatches between TOS and the yard (target zero)."]},day:[{time:"06:30",vi:"Nhận ca, rà soát tình trạng bãi, container lạnh, hàng nguy hiểm và kế hoạch tàu trong ngày.",en:"Take over the shift and review yard status, reefers, dangerous goods and today's vessel plan."},{time:"08:00",vi:"Lập kế hoạch bãi cho tàu sắp cập, phân khu theo cảng đích và trọng lượng.",en:"Plan the yard for the next vessel, zoning by destination and weight."},{time:"11:00",vi:"Điều độ thiết bị giờ cao điểm cổng, xử lý xe chờ lâu và container sai vị trí.",en:"Dispatch equipment during gate peaks and fix long truck waits and misplaced boxes."},{time:"14:00",vi:"Kiểm tra khu DG, khu lạnh; đối chiếu dữ liệu TOS với kiểm đếm thực tế.",en:"Inspect the DG and reefer areas and reconcile TOS data with a physical check."},{time:"17:30",vi:"Tính phí lưu bãi các lô giao trong ngày, bàn giao ca và báo cáo năng suất.",en:"Calculate storage for today's deliveries, hand over the shift and report productivity."}],mistakes:{vi:["Xếp container hàng nguy hiểm vào khu hàng thường hoặc cạnh khu lạnh, vi phạm tách biệt.","Tính ngày lưu bãi không đếm ngày dỡ hoặc ngày lấy ra, bỏ sót phụ thu hàng nguy hiểm.","Di chuyển container mà không cập nhật TOS, gây mất dấu container và rủi ro an toàn."],en:["Placing DG containers among general cargo or next to reefers, breaching segregation.","Leaving out the discharge or gate-out day when counting storage, or missing the DG surcharge.","Moving containers without updating the TOS, losing track of boxes and creating safety risks."]},career:[{vi:"Nhân viên kiểm đếm bãi",en:"Yard checker"},{vi:"Chuyên viên điều độ bãi container",en:"Container yard planner"},{vi:"Trưởng ca khai thác",en:"Operations shift manager"},{vi:"Giám đốc khai thác cảng",en:"Terminal operations director"}],glossary:[{term:"TOS",vi:"Hệ thống quản lý khai thác cảng: kế hoạch tàu, bãi, cổng và thiết bị.",en:"Terminal operating system for vessel, yard, gate and equipment planning."},{term:"TEU",vi:"Đơn vị tương đương container 20 feet, dùng đo sức chứa bãi và tàu.",en:"Twenty-foot equivalent unit used to measure yard and vessel capacity."},{term:"Dwell time",vi:"Thời gian lưu bãi của container từ khi dỡ xuống đến khi lấy ra.",en:"Time a container stays in the yard from discharge to gate-out."},{term:"Segregation",vi:"Tách biệt: khoảng cách hoặc ngăn cách bắt buộc giữa các loại hàng nguy hiểm không tương thích.",en:"Required distance or separation between incompatible dangerous goods."},{term:"Reefer plug",vi:"Ổ cắm điện cấp nguồn cho container lạnh tại bãi.",en:"Power outlet that supplies a refrigerated container in the yard."}],quiz:[{q:{vi:"Container dỡ ngày 05, lấy ra ngày 12 cùng tháng, miễn phí 4 ngày, tính cả ngày dỡ và ngày lấy. Số ngày tính phí là bao nhiêu?",en:"A container is discharged on the 5th and collected on the 12th, with 4 free days and both days counted. How many days are charged?"},options:{vi:["3 ngày","4 ngày","7 ngày","8 ngày"],en:["3 days","4 days","7 days","8 days"]},answer:1,explain:{vi:"Từ ngày 05 đến 12 tính cả hai đầu là 8 ngày; trừ 4 ngày miễn phí còn 4 ngày tính phí.",en:"From the 5th to the 12th inclusive is 8 days; minus 4 free days leaves 4 chargeable days."}},{q:{vi:"Văn bản nào quy định tách biệt hàng nguy hiểm khi vận chuyển container đường biển?",en:"Which instrument sets segregation rules for dangerous goods in sea container transport?"},options:{vi:["Incoterms 2020","UCP 600","ISO 9001","Bộ luật IMDG"],en:["Incoterms 2020","UCP 600","ISO 9001","The IMDG Code"]},answer:3,explain:{vi:"Bộ luật IMDG của IMO quy định phân loại, đóng gói, ghi nhãn và tách biệt hàng nguy hiểm.",en:"The IMO IMDG Code governs classification, packing, labelling and segregation of dangerous goods."}},{q:{vi:"Khu DG đầy, tổ trưởng đề nghị để tạm container hàng nguy hiểm ở khu thường và không cập nhật TOS. Bạn làm gì?",en:"The DG area is full and a foreman proposes parking a DG box in a general block without updating the TOS. What do you do?"},options:{vi:["Từ chối, bố trí khu DG hoặc khu dự phòng được duyệt, cập nhật TOS và báo trưởng ca","Đồng ý vì chỉ qua đêm","Để trên xe đầu kéo, không báo ai","Cập nhật TOS sau khi đã chuyển đi"],en:["Refuse, use the DG area or approved overflow, update the TOS and inform the supervisor","Agree since it is only overnight","Leave it on a tractor and tell no one","Update the TOS after it is moved"]},answer:0,explain:{vi:"Xếp sai khu làm mất tách biệt và che giấu vị trí hàng nguy hiểm khi có sự cố cháy nổ.",en:"Wrong placement breaks segregation and hides the DG position from responders in a fire."}},{q:{vi:"Vì sao phải xếp container theo trọng lượng và cảng đích?",en:"Why stack containers by weight and port of discharge?"},options:{vi:["Để giảm phí lưu bãi","Để tăng số container lạnh","Để giảm đảo chuyển và bảo đảm ổn định khi xếp tàu","Để rút ngắn thủ tục hải quan"],en:["To reduce storage charges","To increase reefer count","To cut rehandles and support vessel stability","To shorten customs formalities"]},answer:2,explain:{vi:"Xếp đúng thứ tự giúp lấy container theo kế hoạch xếp tàu mà không đảo chuyển, giữ ổn định tàu.",en:"Proper stacking lets boxes be picked in loading order without rehandles and supports vessel stability."}}],tools_en:["Terminal operating system (TOS)","OCR gates for container and plate recognition","Vehicle-mounted terminals (VMT) on cranes, trucks","Reefer container monitoring system","Vessel stowage planning software"]}}})})(window.KKR);
